// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 질문 상세 (23번)" (567e93da9c7c4c88beba5717d9649489).
import "./QuestionDetail.css";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { getErrorCode, getErrorMessage } from "../api/client";
import {
  deleteQuestion,
  getQuestion,
  readQuestionId,
  type Grade,
  type QuestionDetail as Question,
} from "../api/question";
import Header from "../components/Header";
import { useAuth } from "../hooks/useAuth";

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  "body {\n      background-color: #FFFDF5;\n      background-image: radial-gradient(#d4cfbe 1px, transparent 1px);\n      background-size: 20px 20px;\n    }\n  \n\n    .neo-btn {\n      transition: all 0.15s ease-in-out;\n    }\n    .neo-btn:hover {\n      transform: translate(2px, 2px);\n      box-shadow: 2px 2px 0px #121212;\n    }\n    .neo-btn:active {\n      transform: translate(4px, 4px);\n      box-shadow: 0px 0px 0px #121212;\n    }";

const LIST_PATH = "/questions";

const GRADES: Record<Grade, { label: string; color: string }> = {
  BRONZE: { label: "브론즈", color: "#CD7F32" },
  SILVER: { label: "실버", color: "#9CA3AF" },
  GOLD: { label: "골드", color: "#EAB308" },
  PLATINUM: { label: "플래티넘", color: "#06B6D4" },
};

// "2026-11-12T10:00:00" → "2026.11.12"
const formatDate = (dateTime: string) => dateTime.slice(0, 10).replaceAll("-", ".");

// 경력을 등록하지 않았으면 닉네임만 표시한다 (REQ-QNA-004, docs/api.md 작성자 정보).
function writerSummary({ careerYears, techStacks, grade, acceptRate }: Question["writer"]) {
  if (careerYears === null) return null;
  const career = careerYears === 0 ? "신입" : `${careerYears}년차`;
  return [
    career,
    ...(techStacks.length > 0 ? [techStacks.join(", ")] : []),
    GRADES[grade].label,
    `채택률 ${acceptRate}%`,
  ].join(" · ");
}

function StatusBox({ children }: { children: ReactNode }) {
  return (
    <div className="bg-white border-thick border-neoBlack rounded-xl shadow-brutal p-10 text-center text-sm font-semibold text-gray-600">
      {children}
    </div>
  );
}

// REQ-QUESTION-007: 삭제 전 이중 확인 (DeleteAcceptModal 화면의 삭제 확인 카드 디자인)
function DeleteConfirmModal({
  deleting,
  error,
  onCancel,
  onConfirm,
}: {
  deleting: boolean;
  error: string | null;
  onCancel: () => void;
  onConfirm: () => void;
}) {
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-6"
      style={{ backgroundColor: "rgba(255, 253, 245, 0.55)", backdropFilter: "blur(8px)" }}
      role="dialog"
      aria-modal="true"
      aria-labelledby="delete-modal-title"
    >
      <div className="relative w-full max-w-md bg-white border-thick border-neoBlack rounded-[14px] shadow-brutal p-8 md:p-10">
        <div className="absolute top-4 left-4 flex items-center gap-1.5">
          <span className="w-3 h-3 rounded-full bg-[#E11D48] border-[1.5px] border-black"></span>
          <span className="text-xs font-mono font-bold tracking-tight text-gray-500 uppercase">Warning</span>
        </div>
        <div className="pt-6 text-center space-y-2">
          <h2 className="text-2xl font-black tracking-tight text-[#111111]" id="delete-modal-title">
            정말 삭제하시겠습니까?
          </h2>
          <p className="text-base font-bold text-[#E11D48]">삭제한 질문은 복구할 수 없습니다.</p>
        </div>
        {error && (
          <p
            className="mt-6 px-4 py-3 bg-white border-thick border-neoBlack rounded-xl text-sm font-bold text-center text-[#111111]"
            role="alert"
          >
            {error}
          </p>
        )}
        <div className="pt-8 flex items-center justify-center gap-4">
          <button
            autoFocus
            className="w-32 h-11 px-6 font-bold text-sm bg-white hover:bg-gray-100 text-[#111111] border-thick border-neoBlack rounded-lg shadow-brutal-sm"
            type="button"
            onClick={onCancel}
          >
            취소
          </button>
          <button
            className="w-32 h-11 px-6 font-bold text-sm bg-[#E11D48] hover:bg-[#BE123C] text-white border-thick border-neoBlack rounded-lg shadow-brutal-sm disabled:opacity-60 disabled:cursor-not-allowed"
            type="button"
            disabled={deleting || error !== null}
            onClick={onConfirm}
          >
            {deleting ? "삭제 중..." : "삭제"}
          </button>
        </div>
      </div>
    </div>
  );
}

type LoadState = { status: "loading" } | { status: "error"; message: string } | { status: "done"; question: Question };

export default function QuestionDetail() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [searchParams] = useSearchParams();
  const questionId = readQuestionId(searchParams.get("questionId"));
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [menuOpen, setMenuOpen] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  // 조회할 때마다 조회수가 오르므로 같은 질문은 한 번만 요청한다.
  // (개발 모드 StrictMode는 effect를 두 번 실행해 조회수가 2씩 오르는 것을 막는다. ref는 두 번째 실행에도 유지된다.)
  const requestedId = useRef<number | null>(null);
  useEffect(() => {
    if (questionId === null) {
      setState({ status: "error", message: "존재하지 않는 질문입니다." });
      return;
    }
    if (requestedId.current === questionId) return;
    requestedId.current = questionId;
    setState({ status: "loading" });
    getQuestion(questionId)
      .then((question) => {
        if (requestedId.current === questionId) setState({ status: "done", question });
      })
      .catch((error: unknown) => {
        if (requestedId.current !== questionId) return;
        const notFound = getErrorCode(error) === "QUESTION_NOT_FOUND";
        setState({
          status: "error",
          message: notFound ? "삭제되었거나 존재하지 않는 질문입니다." : getErrorMessage(error),
        });
      });
  }, [questionId]);

  // 메뉴 바깥을 누르면 닫는다.
  useEffect(() => {
    if (!menuOpen) return;
    function handleClick(event: MouseEvent) {
      if (!menuRef.current?.contains(event.target as Node)) setMenuOpen(false);
    }
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [menuOpen]);

  const question = state.status === "done" ? state.question : null;
  // 수정은 작성자만, 삭제는 작성자와 관리자 (REQ-QNA-001). 서버에서도 다시 검사한다.
  const isWriter = question !== null && user?.memberId === question.writer.memberId;
  const canDelete = isWriter || user?.role === "ROLE_ADMIN";

  function openDeleteConfirm() {
    setMenuOpen(false);
    setDeleteError(null);
    setConfirmOpen(true);
  }

  async function handleDelete() {
    if (question === null) return;
    setDeleting(true);
    try {
      await deleteQuestion(question.questionId);
      navigate(LIST_PATH, { replace: true }); // REQ-QUESTION-007: 삭제 후 질문 목록으로 이동
    } catch (error) {
      // 409 QUESTION_HAS_ACCEPTED_ANSWER 등 서버가 알려준 이유를 모달에 보여 준다.
      setDeleteError(getErrorMessage(error));
      setDeleting(false);
    }
  }

  return (
    <div id="page-question-detail">
      <style>{css}</style>
      <div
        className="text-neoBlack font-sans min-h-screen flex flex-col antialiased selection:bg-neoYellow selection:text-black"
        style={{
          backgroundColor: "rgb(255, 253, 245)",
          backgroundImage: "radial-gradient(rgb(217, 212, 195) 1px, transparent 1px)",
          backgroundSize: "18px 18px",
        }}
      >
        <Header />
        <main
          className="flex-grow max-w-5xl w-full mx-auto px-4 sm:px-6 py-8 md:py-10"
          aria-busy={state.status === "loading"}
        >
          {state.status === "loading" && <StatusBox>질문을 불러오는 중입니다...</StatusBox>}
          {state.status === "error" && (
            <StatusBox>
              <p role="alert">{state.message}</p>
              <Link
                className="neo-btn inline-block mt-5 px-4 py-2 bg-white border-thick border-neoBlack rounded-xl shadow-brutal-sm text-sm font-bold text-neoBlack"
                to={LIST_PATH}
              >
                질문 목록으로 가기
              </Link>
            </StatusBox>
          )}
          {question && (
            <>
              {/* BEGIN: QuestionDetailCard */}
              <article
                className="bg-white border-thick border-neoBlack rounded-xl shadow-brutal p-6 md:p-8"
                data-purpose="question-detail"
              >
                {/* Question Card Header: Badge, Title, More Dropdown Trigger */}

                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b-thick border-neoBlack pb-5">
                  <div className="flex flex-wrap items-center gap-3">
                    {question.accepted ? (
                      <span className="px-3.5 py-1 text-sm font-bold bg-neoGreen text-neoBlack border-thick border-neoBlack rounded-full tracking-wide">
                        해결됨
                      </span>
                    ) : (
                      <span className="px-3.5 py-1 text-sm font-bold bg-white text-gray-600 border-thick border-neoBlack rounded-full tracking-wide">
                        미해결
                      </span>
                    )}
                    <span className="px-3 py-1 text-xs font-bold bg-neoYellow text-neoBlack border-thick border-neoBlack rounded-full">
                      {question.category.name}
                    </span>
                    <h1 className="text-xl sm:text-[22px] font-[800] text-neoBlack leading-snug break-all">
                      {question.title}
                    </h1>
                  </div>

                  {/* Author/Admin Dropdown Actions — 작성자·관리자에게만 보인다 */}

                  {canDelete && (
                    <div className="relative self-end md:self-auto" ref={menuRef}>
                      <button
                        aria-expanded={menuOpen}
                        aria-haspopup="menu"
                        aria-label="추가 옵션"
                        className="neo-btn p-2 w-10 h-10 flex items-center justify-center bg-white border-thick border-neoBlack rounded-xl shadow-brutal text-neoBlack font-bold hover:bg-gray-100"
                        id="more-options-btn"
                        type="button"
                        onClick={() => setMenuOpen((open) => !open)}
                      >
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                          <path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z"></path>
                        </svg>
                      </button>
                      {menuOpen && (
                        <div
                          className="absolute right-0 mt-2 w-28 bg-white border-thick border-neoBlack rounded-xl shadow-brutal z-30 py-1 font-bold text-sm divide-y-2 divide-neoBlack overflow-hidden"
                          id="more-options-menu"
                          role="menu"
                        >
                          {isWriter && (
                            <Link
                              className="block px-4 py-2 hover:bg-yellow-100 text-neoBlack text-center"
                              role="menuitem"
                              to={`/question-edit?questionId=${question.questionId}`}
                            >
                              수정
                            </Link>
                          )}
                          <button
                            className="w-full text-center px-4 py-2 hover:bg-red-50 text-neoRed"
                            role="menuitem"
                            type="button"
                            onClick={openDeleteConfirm}
                          >
                            삭제
                          </button>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {/* Author Metadata Info Bar */}

                <div className="py-4 border-b-thick border-neoBlack flex flex-wrap items-center justify-between gap-y-3 text-sm">
                  <div className="flex flex-wrap items-center gap-2.5">
                    <div className="flex items-center gap-1 font-bold text-neoBlack">
                      <span>{question.writer.nickname}</span>
                      <span
                        className="inline-flex items-center justify-center text-sm"
                        style={{ color: GRADES[question.writer.grade].color }}
                        title={`${GRADES[question.writer.grade].label} 등급`}
                      >
                        ★
                      </span>
                    </div>
                    {writerSummary(question.writer) && (
                      <>
                        <span className="text-gray-300">|</span>
                        <span className="text-gray-600 font-medium text-xs sm:text-sm">
                          {writerSummary(question.writer)}
                        </span>
                      </>
                    )}
                  </div>

                  {/* Post Stats: Date & Views */}

                  <div className="flex items-center gap-3 text-xs sm:text-sm font-semibold text-gray-500">
                    <time dateTime={question.createdAt}>{formatDate(question.createdAt)}</time>
                    <span className="text-gray-300">·</span>
                    <span>조회 {question.viewCount}</span>
                  </div>
                </div>

                {/* Question Tags Section */}

                {question.tags.length > 0 && (
                  <div className="py-4 flex flex-wrap items-center gap-2">
                    {question.tags.map((tag) => (
                      <span
                        key={tag}
                        className="inline-block px-3 py-1 bg-white border-thick border-neoBlack rounded-xl shadow-brutal-sm text-xs font-bold"
                      >
                        # {tag}
                      </span>
                    ))}
                  </div>
                )}

                {/* Post Main Body Content — 마크다운 렌더링·코드 하이라이팅은 #62. 지금은 원문을 그대로 보여 준다 (React가 HTML을 이스케이프). */}

                <div className="mt-4 text-gray-900 leading-relaxed font-normal whitespace-pre-wrap break-words">
                  {question.content}
                </div>

                {/* Card Footer Actions: Like & Report — 좋아요(#65·#66), 신고 화면 연결 전이라 비활성 */}

                <div className="mt-8 pt-6 border-t-thick border-neoBlack flex items-center gap-3">
                  <button
                    className="inline-flex items-center gap-2 px-4 py-2 bg-white border-thick border-neoBlack rounded-xl shadow-brutal text-sm font-bold disabled:cursor-not-allowed"
                    disabled
                    id="like-button"
                    title="준비 중인 기능입니다"
                    type="button"
                  >
                    <span className="text-red-500 text-base">{question.liked ? "♥" : "♡"}</span>
                    <span>
                      {"좋아요 "}
                      <span id="like-counter">{question.likeCount}</span>
                    </span>
                  </button>
                  <button
                    className="inline-flex items-center px-4 py-2 bg-white border-thick border-neoBlack rounded-xl shadow-brutal text-sm font-bold text-gray-700 disabled:cursor-not-allowed"
                    disabled
                    title="준비 중인 기능입니다"
                    type="button"
                  >
                    신고
                  </button>
                </div>
              </article>
              {/* END: QuestionDetailCard */}
              <div className="mt-8 text-center" data-purpose="bottom-indicator">
                <div className="inline-flex items-center gap-2 text-sm font-extrabold text-neoBlack bg-white px-5 py-2.5 border-thick border-neoBlack rounded-xl shadow-brutal">
                  <span className="text-xs">▼</span> <span>답변 {question.answerCount}개 · 답변 작성 · 유사 질문</span>
                </div>
              </div>
            </>
          )}
        </main>
        {confirmOpen && (
          <DeleteConfirmModal
            deleting={deleting}
            error={deleteError}
            onCancel={() => setConfirmOpen(false)}
            onConfirm={handleDelete}
          />
        )}
      </div>
    </div>
  );
}
